// The verifier's attestation of the identity it sets on a request it lets through: `x-dnsid-attestation`, an HMAC-SHA256
// under a key only this deployment holds (DNSID_ATTESTATION_KEY, generated by Terraform for each deployment and given to
// the verifier and Demo Bank alone), over the verified domain, the governance ID and the time it was made.
//
// Why: Google's load balancer can forward a request to Demo Bank without evaluating the authorization policy for some
// minutes after the policy is created (seen live on 2026-11-14, docs/live-tests.md). In that window a caller's own
// `x-dnsid-*` headers would reach Demo Bank unremoved. Demo Bank accepts an identity only with a valid attestation
// made within ATTESTATION_MAX_AGE_S, which a caller can't make without the key (origin/server.ts checks it).
//
//   x-dnsid-attestation: v1.<unix seconds>.<base64url HMAC-SHA256(key, "dnsid-attestation v1\n<seconds>\n<domain>\n<governance>")>
//
// The key and the header's value are never logged.

import { createHmac } from 'node:crypto';

export const ATTESTATION_HEADER = 'x-dnsid-attestation';
export const ATTESTATION_KEY_SETTING = 'DNSID_ATTESTATION_KEY';
/** How old an attestation Demo Bank still accepts, and how far ahead of its own clock. */
export const ATTESTATION_MAX_AGE_S = 30;
export const ATTESTATION_MAX_FUTURE_S = 5;

/** The key's form: 32 to 256 characters from the base64url alphabet; its bytes are the key. */
const KEY_FORM = /^[A-Za-z0-9_-]{32,256}$/;

export class AttestationKeyError extends Error {
  constructor() {
    super(`${ATTESTATION_KEY_SETTING} must be set to 32 to 256 characters from A-Z, a-z, 0-9, "-" and "_"`);
    this.name = 'AttestationKeyError';
  }
}

/** The attestation key from its setting. Throws AttestationKeyError (which never repeats the value) unless well formed. */
export function attestationKeyFromSetting(value: string | undefined): Buffer {
  if (value === undefined || !KEY_FORM.test(value)) throw new AttestationKeyError();
  return Buffer.from(value, 'ascii');
}

/** What is signed: the version, the time and both identity values, one per line (none of them can hold a line break). */
export function attestationInput(seconds: number, domain: string, governanceId: string): string {
  return `dnsid-attestation v1\n${seconds}\n${domain}\n${governanceId}`;
}

/** The header value for `domain` and `governanceId`, made at `nowMs` (Date.now() by default). */
export function attest(key: Uint8Array, domain: string, governanceId: string, nowMs: number = Date.now()): string {
  const seconds = Math.floor(nowMs / 1000);
  const mac = createHmac('sha256', key).update(attestationInput(seconds, domain, governanceId), 'utf8').digest('base64url');
  return `v1.${seconds}.${mac}`;
}
